<script setup lang="ts">
import { onMounted, onUnmounted, reactive, ref } from 'vue';
import { ElMessage, ElMessageBox } from 'element-plus';
type Row=Record<string,any>;
const props=defineProps<{api:(path:string,method?:string,body?:any,signal?:AbortSignal)=>Promise<any>}>();
const form=reactive({provider:'none',site_key:'',secret:'',current_password:''}),hosts=ref(''),configured=ref(false),busy=ref(false),rows=ref<Row[]>([]),page=ref(1),more=ref(false),error=ref(''),loaded=ref(false),loading=ref(true);
let controller:AbortController|undefined,alive=true;
const time=(v:string)=>new Date(v).toLocaleString('zh-CN',{hour12:false});
async function load(includeSettings=true){
 controller?.abort();controller=new AbortController();const signal=controller.signal;error.value='';loading.value=true;
 try{const [settings,blocks]=await Promise.all([includeSettings?props.api('/auth/protection/settings','GET',undefined,signal):Promise.resolve(null),props.api('/auth/blocked-ips?page='+page.value,'GET',undefined,signal)]);
 if(!alive||signal.aborted)return;
 if(settings){form.provider=settings.provider;form.site_key=settings.site_key;hosts.value=(settings.hostnames?.length?settings.hostnames:[location.hostname.replace(/^\[|\]$/g,'')]).join('\n');configured.value=settings.secret_configured;loaded.value=true;}
 rows.value=blocks.items;more.value=blocks.has_more;
 }catch(e){if(alive&&!signal.aborted)error.value=(e as Error).message}finally{if(alive&&!signal.aborted)loading.value=false}
}
defineExpose({refresh:()=>load()});
async function save(){busy.value=true;try{await props.api('/auth/protection/settings','PATCH',{...form,hostnames:hosts.value.split(/[\n,]+/).map(v=>v.trim()).filter(Boolean)});form.secret='';form.current_password='';await load();ElMessage.success('登录防护已保存');}catch(e){ElMessage.error((e as Error).message)}finally{busy.value=false;form.current_password=''}}
async function unblock(row:Row){try{await ElMessageBox.confirm(`解除 ${row.source_ip} 的登录封禁并清空本轮错误计数？`,'解除封禁',{confirmButtonText:'解除',cancelButtonText:'取消',type:'warning'})}catch{return}busy.value=true;try{await props.api('/auth/blocked-ips/'+row.id,'DELETE');await load(false);ElMessage.success('已解除封禁');}catch(e){ElMessage.error((e as Error).message)}finally{busy.value=false}}
onMounted(()=>void load());onUnmounted(()=>{alive=false;controller?.abort();form.secret='';form.current_password='';});
</script>
<template><div class="login-protection"><p v-if="error" class="captcha-error" role="alert">{{error}} <button class="text-action" @click="load()">重试</button></p><section class="panel"><div class="panel-heading"><h3>人机验证</h3><span class="subtle">60 秒内错误 5 次，封禁来源 IP 24 小时</span></div><form class="editor protection-form" @submit.prevent="save"><label>验证服务<select v-model="form.provider" :disabled="loading" @change="form.site_key='';form.secret='';configured=false"><option value="none">不启用验证码</option><option value="turnstile">Cloudflare Turnstile</option><option value="recaptcha">Google reCAPTCHA v2</option><option value="geetest">极验第四代</option></select></label><template v-if="form.provider!=='none'"><label>站点标识（Site Key / Captcha ID）<input v-model="form.site_key" required maxlength="256" autocomplete="off"/></label><label>服务密钥<input v-model="form.secret" type="password" maxlength="512" autocomplete="new-password" :placeholder="configured?'已配置；不更换服务或站点时可留空保留':''"/></label><label>允许的网站主机<textarea v-model="hosts" rows="2" required placeholder="guard.example.com 或 192.0.2.10，不含端口或路径"/></label><p class="form-note">先在服务商后台创建站点并允许当前主机名。服务密钥加密保存，不会返回浏览器。验证服务异常时拒绝登录，不自动放行。</p></template><label>当前密码<input v-model="form.current_password" type="password" required maxlength="72" autocomplete="current-password"/></label><div class="dialog-actions"><button class="primary-action" :disabled="busy||!loaded||loading" type="submit">保存</button></div></form></section><section class="panel"><div class="panel-heading"><h3>登录封禁</h3><span class="subtle">到期自动解除，SSH IP 白名单不豁免此规则</span></div><div v-if="!rows.length" class="empty-state">暂无封禁 IP</div><div v-else class="table-scroll"><table class="data-table"><thead><tr><th>来源 IP</th><th>到期时间</th><th>操作</th></tr></thead><tbody><tr v-for="row in rows" :key="row.id"><td>{{row.source_ip}}</td><td>{{time(row.blocked_until)}}</td><td><button class="text-action" :disabled="busy" @click="unblock(row)">解除</button></td></tr></tbody></table></div><div class="pagination"><span>第 {{page}} 页</span><button class="secondary-action" :disabled="page===1||busy" @click="page--;load(false)">上一页</button><button class="secondary-action" :disabled="!more||busy" @click="page++;load(false)">下一页</button></div></section></div></template>
